import json

with open('/app/resources/treasury_bulletin_2010_03.json', 'r') as f:
    data = json.load(f)

# Look for all tables containing 2004 data with exchange rates
for i, elem in enumerate(data['document']['elements']):
    if 'content' in elem and elem['content']:
        content = str(elem['content'])
        if '2004' in content and ('March' in content or 'Mar' in content):
            if 'exchange' in content.lower() or 'rate' in content.lower():
                print(f"Element {i}: {content[:1000]}")
                print("---")
EOF
